const writes = [];
page.on('request', r => { if (r.url().includes('/tag_config/') && r.method() !== 'GET') writes.push(r.method()); });
const dlg = page.getByRole('dialog');
const pick = async (name) => {
  await dlg.getByRole('combobox').last().click();
  await page.locator('[data-radix-popper-content-wrapper]').last().getByRole('option', { name }).first().click();
  await page.waitForTimeout(600);
};
await dlg.getByRole('button', { name: 'Remove organization' }).click();
await page.waitForTimeout(500);
await pick('Nurse');
const afterPickNurse = await dlg.locator('p.text-sky-900').allTextContents();
await dlg.getByRole('button', { name: 'Remove organization' }).click();
await page.waitForTimeout(500);
const labelAfterRemovingNurse = (await dlg.getByRole('combobox').last().textContent())?.trim();
await pick('Nurse');
const updateEnabled = await dlg.getByRole('button', { name: 'Update tag config' }).isEnabled();
const resp = page.waitForResponse(r => r.url().includes('/tag_config/') && r.request().method() === 'PUT');
await dlg.getByRole('button', { name: 'Update tag config' }).click();
const r = await resp;
const body = await r.json();
return { afterPickNurse, labelAfterRemovingNurse, updateEnabled, writesBeforeSave: writes.length - 1, putStatus: r.status(), savedOrg: body.organization?.name };

