await dlg.getByRole('button', { name: 'Remove organization' }).click();
await page.waitForTimeout(500);
const resp = page.waitForResponse(r => r.url().includes('/tag_config/') && r.request().method() === 'PUT');
await dlg.getByRole('button', { name: 'Update tag config' }).click();
const r = await resp;
const sent = JSON.parse(r.request().postData() || '{}');
const body = await r.json();
return { status: r.status(), sentOrganization: sent.organization, savedOrganization: body.organization ?? null };

